const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let idx = 0;

const E = data[idx++];
const R = data[idx++];

const adj = Array.from({ length: E + 1 }, () => []);
for (let i = 0; i < R; i++) {
  const A = data[idx++];
  const B = data[idx++];
  const C = data[idx++];
  adj[A].push([B, C]);
  adj[B].push([A, C]);
}

const K = data[idx++];
const queries = [];
for (let i = 0; i < K; i++) {
  const X = data[idx++];
  const T = data[idx++];
  queries.push([X, T]);
}

// Find all cycles in the cactus graph
const visited = new Array(E + 1).fill(false);
const parent = new Array(E + 1).fill(0);
const parentLen = new Array(E + 1).fill(0);
const depth = new Array(E + 1).fill(0);
const iter = new Array(E + 1).fill(0);
const cycles = [];

for (let start = 1; start <= E; start++) {
  if (visited[start]) continue;

  visited[start] = true;
  parent[start] = 0;
  depth[start] = 0;
  const stack = [start];

  while (stack.length > 0) {
    const v = stack[stack.length - 1];

    if (iter[v] < adj[v].length) {
      const [to, w] = adj[v][iter[v]++];
      if (to === parent[v]) continue;

      if (!visited[to]) {
        visited[to] = true;
        parent[to] = v;
        parentLen[to] = w;
        depth[to] = depth[v] + 1;
        stack.push(to);
      } else if (depth[to] < depth[v]) {
        let cur = v;
        const vertices = [];
        let sum = 0;

        while (cur !== to) {
          vertices.push(cur);
          sum += parentLen[cur];
          cur = parent[cur];
        }
        vertices.push(to);

        const len = sum + w;
        cycles.push({ len, vertices });
      }
    } else {
      stack.pop();
    }
  }
}

class MinHeap {
  constructor() {
    this.heap = [];
  }

  push(d, v) {
    const heap = this.heap;
    heap.push([d, v]);
    let i = heap.length - 1;

    while (i > 0) {
      const p = (i - 1) >> 1;
      if (heap[p][0] <= heap[i][0]) break;
      const tmp = heap[p];
      heap[p] = heap[i];
      heap[i] = tmp;
      i = p;
    }
  }

  pop() {
    const heap = this.heap;
    if (heap.length === 0) return null;

    const top = heap[0];
    const last = heap.pop();

    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      const n = heap.length;

      while (true) {
        const l = i * 2 + 1;
        const r = i * 2 + 2;
        let smallest = i;

        if (l < n && heap[l][0] < heap[smallest][0]) smallest = l;
        if (r < n && heap[r][0] < heap[smallest][0]) smallest = r;

        if (smallest === i) break;

        const tmp = heap[i];
        heap[i] = heap[smallest];
        heap[smallest] = tmp;
        i = smallest;
      }
    }

    return top;
  }

  size() {
    return this.heap.length;
  }
}

const out = [];

for (let qi = 0; qi < K; qi++) {
  const X = queries[qi][0];
  const T = queries[qi][1];

  const dist = new Array(E + 1).fill(Infinity);
  dist[X] = 0;

  const heap = new MinHeap();
  heap.push(0, X);

  while (heap.size() > 0) {
    const [d, v] = heap.pop();
    if (d !== dist[v]) continue;

    const neighbors = adj[v];
    for (let i = 0; i < neighbors.length; i++) {
      const to = neighbors[i][0];
      const w = neighbors[i][1];
      const nd = d + w;

      if (nd < dist[to]) {
        dist[to] = nd;
        heap.push(nd, to);
      }
    }
  }

  let ans = Infinity;

  for (let ci = 0; ci < cycles.length; ci++) {
    const cyc = cycles[ci];
    if (cyc.len < T) continue;

    let minD = Infinity;
    const verts = cyc.vertices;

    for (let vi = 0; vi < verts.length; vi++) {
      const d = dist[verts[vi]];
      if (d < minD) minD = d;
    }

    if (minD !== Infinity) {
      const val = 2 * minD + cyc.len;
      if (val < ans) ans = val;
    }
  }

  out.push(ans === Infinity ? -1 : ans);
}

console.log(out.join('\n'));
